mapper.select:
select uuid,warehouse_id,warehouse_name,owner_unit,warehouse_status,charge_user,phone_num,address
from idevelop_warehouse where is_deleted = 0

    and warehouse_name like concat('%',#{warehouse.warehouseName},'%')


    and warehouse_id = #{warehouse.warehouseId}


    and owner_unit = #{warehouse.owner_unit}

select warehouse_name,owner_unit,warehouse_id,owner_unit_id,uuid,address from idevelop_warehouse
AND warehouse_status = 1 and is_deleted = 0
    
        AND owner_unit_id = #{ownerUnitId}

select uuid,warehouse_name,owner_unit,warehouse_id,owner_unit_id,dev_size,ware_size,out_size,last_update_time
from idevelop_warehouse
is_deleted = 0
    
        and owner_unit_id = #{ownerUnitId}
    
    
        and warehouse_name = #{ownerUnitName}
    
    
        and warehouse_name = #{warehouseName}
    
    
        and warehouse_id = #{warehouseId}
    

order by dev_size desc limit 0,8

SELECT iw.*,sum(idi.inventory_num) as devSize FROM idevelop_warehouse iw left join `idevelop_device_inventory` idi on iw.uuid=idi.warehouse where iw.is_deleted=0
AND owner_unit_id = #{ownerUnitId}
GROUP BY iw.uuid

select *
from idevelop_warehouse
where is_deleted = 0

    AND owner_unit_id = #{warehouse.ownerUnitId}

LIMIT #{startIndex},#{size}

select uuid,warehouse_name,region_code,owner_unit_id,owner_unit from idevelop_warehouse where is_deleted = 0
and region_code like concat(#{regionCode},'%')
and warehouse_name = #{name}
